"use client";

import { cn } from "cn";
import { CheckIcon, SearchIcon } from "lucide-react";
/**
 * Command primitives in the aria-sera style.
 *
 * Why: a searchable menu built on react-aria-components, used as the option
 * list for a combobox style picker. Generated by shadcn.
 *
 * Used by: components/ui/multi-select.tsx.
 */

import type * as React from "react";
import {
	Autocomplete,
	type AutocompleteProps,
	Collection,
	composeRenderProps,
	Header,
	Input,
	type InputProps,
	Menu,
	MenuItem,
	type MenuItemProps,
	type MenuProps,
	MenuSection,
	type MenuSectionProps,
	SearchField,
	Separator,
	type SeparatorProps,
	useFilter,
} from "react-aria-components";
import { Dialog, DialogDescription, DialogHeader, DialogTitle } from "./dialog";
import { InputGroup, InputGroupAddon } from "./input-group";

function Command({
	className,
	dir,
	style,
	...props
}: Omit<AutocompleteProps, "className" | "style"> & {
	className?: string;
	dir?: React.HTMLAttributes<HTMLDivElement>["dir"];
	style?: React.CSSProperties;
}) {
	const { contains } = useFilter({ sensitivity: "base" });
	return (
		<div
			data-slot="command"
			dir={dir}
			className={cn(
				"flex size-full flex-col overflow-hidden bg-popover text-popover-foreground",
				className,
			)}
			style={style}
		>
			<Autocomplete {...props} filter={props.filter || contains}>
				{props.children}
			</Autocomplete>
		</div>
	);
}

function CommandDialog({
	title = "Command Palette",
	description = "Search for a command to run...",
	children,
	open,
	onOpenChange,
	className,
	showCloseButton = false,
	...props
}: Omit<
	React.ComponentProps<typeof Dialog>,
	"children" | "className" | "isOpen" | "onOpenChange"
> & {
	title?: string;
	description?: string;
	open?: boolean;
	onOpenChange?: (isOpen: boolean) => void;
	className?: string;
	showCloseButton?: boolean;
	children: React.ReactNode;
}) {
	return (
		<Dialog
			isOpen={open}
			onOpenChange={onOpenChange}
			className={cn("top-1/3 translate-y-0 overflow-hidden p-0", className)}
			showCloseButton={showCloseButton}
			isDismissable
			{...props}
		>
			<DialogHeader className="sr-only">
				<DialogTitle>{title}</DialogTitle>
				<DialogDescription>{description}</DialogDescription>
			</DialogHeader>
			{children}
		</Dialog>
	);
}

function CommandInput({ className, ...props }: InputProps) {
	return (
		<SearchField
			autoFocus
			aria-label={props.placeholder || "Search"}
			data-slot="command-input-wrapper"
			className="p-1"
		>
			<InputGroup className="border-transparent border-b-input bg-transparent px-3">
				<Input
					{...props}
					data-slot="command-input"
					className={cn(
						"w-full px-2 text-sm outline-hidden disabled:cursor-not-allowed disabled:opacity-50 [&::-webkit-search-cancel-button]:hidden",
						className,
					)}
				/>
				<InputGroupAddon>
					<SearchIcon className="size-3.5 shrink-0 opacity-50" />
				</InputGroupAddon>
			</InputGroup>
		</SearchField>
	);
}

function CommandList<T extends object>({ className, ...props }: MenuProps<T>) {
	return (
		<Menu
			{...props}
			data-slot="command-list"
			className={cn(
				"no-scrollbar max-h-72 scroll-py-1 overflow-x-hidden overflow-y-auto outline-none",
				className,
			)}
		/>
	);
}

function CommandEmpty({ className, ...props }: React.ComponentProps<"div">) {
	return (
		<div
			data-slot="command-empty"
			className={cn("py-6 text-center text-sm", className)}
			{...props}
		/>
	);
}

function CommandGroup<T extends object>({
	className,
	children,
	items,
	heading,
	...props
}: MenuSectionProps<T> & { heading?: string }) {
	return (
		<MenuSection
			data-slot="command-group"
			className={cn(
				"overflow-hidden p-1.5 text-foreground **:[[cmdk-group-heading]]:px-3 **:[[cmdk-group-heading]]:py-2 **:[[cmdk-group-heading]]:text-xs **:[[cmdk-group-heading]]:font-semibold **:[[cmdk-group-heading]]:tracking-wider **:[[cmdk-group-heading]]:text-muted-foreground **:[[cmdk-group-heading]]:uppercase",
				className,
			)}
			{...props}
		>
			{heading && <Header cmdk-group-heading="">{heading}</Header>}
			<Collection items={items}>{children}</Collection>
		</MenuSection>
	);
}

function CommandSeparator({ className, ...props }: SeparatorProps) {
	return (
		<Separator
			data-slot="command-separator"
			className={cn("-mx-1.5 my-1.5 h-px bg-border/50", className)}
			{...props}
		/>
	);
}

function CommandItem<T extends object>({
	className,
	children,
	textValue,
	...props
}: MenuItemProps<T>) {
	return (
		<MenuItem
			{...props}
			data-slot="command-item"
			className={cn(
				"group/command-item relative flex cursor-default items-center gap-2 rounded-none px-3 py-2 text-sm outline-hidden select-none in-data-[slot=dialog-content]:rounded-none data-focused:bg-muted data-focused:text-foreground data-[disabled=true]:pointer-events-none data-[disabled=true]:opacity-50 data-selected:bg-muted data-selected:text-foreground [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-3.5 data-focused:*:[svg]:text-foreground data-selected:*:[svg]:text-foreground",
				className,
			)}
			textValue={
				textValue || (typeof children === "string" ? children : undefined)
			}
		>
			{composeRenderProps(children, (children) => (
				<>
					{children}
					<CheckIcon className="ml-auto opacity-0 group-has-data-[slot=command-shortcut]/command-item:hidden group-data-[checked=true]/command-item:opacity-100 group-data-selected/command-item:opacity-100" />
				</>
			))}
		</MenuItem>
	);
}

function CommandShortcut({
	className,
	...props
}: React.ComponentProps<"span">) {
	return (
		<span
			data-slot="command-shortcut"
			className={cn(
				"ml-auto text-xs tracking-widest text-muted-foreground group-data-focused/command-item:text-foreground group-data-selected/command-item:text-foreground",
				className,
			)}
			{...props}
		/>
	);
}

export {
	Command,
	CommandDialog,
	CommandInput,
	CommandList,
	CommandEmpty,
	CommandGroup,
	CommandItem,
	CommandShortcut,
	CommandSeparator,
};
